<script setup lang="ts">
import { ref, reactive, onMounted } from 'vue'
import { Plus, Search, Camera } from '@element-plus/icons-vue'
import { api, post, put, remove, items, query, errorText } from '../api'
import { useLoad, today } from '../composables'
import { ElMessage, ElMessageBox } from 'element-plus'
import FaceEnrollment from '../components/FaceEnrollment.vue'
const rows=ref<any[]>([]),departments=ref<any[]>([]),total=ref(0),page=ref(1),search=ref(''),departmentId=ref<number|undefined>(),dialog=ref(false),editing=ref<number|null>(null),saving=ref(false),formError=ref(''),faceOpen=ref(false),selected=ref<any>(null),departmentOpen=ref(false),initialPassword=ref(''),credentialOpen=ref(false),createdUsername=ref('')
const blank=()=>({employeeNo:'',name:'',departmentId:undefined as number|undefined,active:true,startDate:today(),endDate:'',username:'',password:'',role:'EMPLOYEE'})
const form=reactive(blank()),departmentName=ref(''),departmentSaving=ref(false)
const {loading,error,load}=useLoad(async()=>{const data=await api('/employees?'+query({page:page.value-1,size:20,keyword:search.value,departmentId:departmentId.value}));rows.value=items(data);total.value=data.total??rows.value.length})
async function loadDepartments(){departments.value=items(await api('/departments?size=200'))}
onMounted(()=>loadDepartments().catch(e=>ElMessage.error(errorText(e))))
function edit(row?:any){editing.value=row?.id??null;Object.assign(form,blank(),row?{employeeNo:row.employeeNo,name:row.name,departmentId:row.departmentId,active:row.active,startDate:row.startDate,endDate:row.endDate||''}:{});formError.value='';dialog.value=true}
async function save(){if(!form.employeeNo.trim()||!form.name.trim()||!form.departmentId||!form.startDate){formError.value='请填写工号、姓名、部门和入职日期';return}if(form.endDate&&form.endDate<form.startDate){formError.value='离职日期不能早于入职日期';return}if(!editing.value&&form.password&&form.password.length<12){formError.value='指定初始密码至少需要12位';return}saving.value=true;formError.value='';try{const payload={...form,endDate:form.endDate||null,username:form.username||undefined,password:form.password||undefined};const data=editing.value?await put(`/employees/${editing.value}`,payload):await post('/employees',payload);dialog.value=false;if(data.initialPassword){initialPassword.value=data.initialPassword;createdUsername.value=data.username||form.username||form.employeeNo;credentialOpen.value=true}ElMessage.success(editing.value?'员工信息已更新':'员工档案及账号已创建');await load()}catch(e){formError.value=errorText(e)}finally{saving.value=false}}
function enroll(row:any){selected.value=row;faceOpen.value=true}
async function deleteFace(row:any){try{await ElMessageBox.confirm(`删除 ${row.name} 的人脸模板后，该员工将无法刷脸打卡。历史考勤记录仍保留。`,'删除人脸模板',{type:'warning',confirmButtonText:'删除模板',cancelButtonText:'取消'});await remove(`/employees/${row.id}/face`);ElMessage.success('人脸模板已删除');load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(errorText(e))}}
async function addDepartment(){if(!departmentName.value.trim())return;departmentSaving.value=true;try{await post('/departments',{name:departmentName.value.trim(),active:true});departmentName.value='';await loadDepartments();ElMessage.success('部门已创建')}catch(e){ElMessage.error(errorText(e))}finally{departmentSaving.value=false}}
async function editDepartment(row:any){try{const {value}=await ElMessageBox.prompt('请输入新的部门名称','修改部门',{inputValue:row.name,inputValidator:v=>!!v?.trim()||'部门名称不能为空',confirmButtonText:'保存',cancelButtonText:'取消'});await put(`/departments/${row.id}`,{name:value.trim(),active:row.active});await loadDepartments();await load()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(errorText(e))}}
async function toggleDepartment(row:any){try{await ElMessageBox.confirm(`确认${row.active?'停用':'启用'}「${row.name}」？`,'更新部门状态',{confirmButtonText:'确认',cancelButtonText:'取消'});await put(`/departments/${row.id}`,{name:row.name,active:!row.active});await loadDepartments()}catch(e){if(e!=='cancel'&&e!=='close')ElMessage.error(errorText(e))}}
</script>
<template><div class="page-head"><div><div class="eyebrow">PEOPLE & ORGANIZATION</div><h1>人员与部门</h1><p>维护人员档案，现场核验身份后录入人脸。</p></div><div class="head-actions"><el-button @click="departmentOpen=true">部门管理</el-button><el-button type="primary" :icon="Plus" @click="edit()">新建员工</el-button></div></div><div class="panel"><div class="toolbar"><el-input v-model="search" placeholder="搜索姓名或工号" :prefix-icon="Search" clearable style="width:240px" @keyup.enter="page=1;load()"/><el-select v-model="departmentId" placeholder="全部部门" clearable style="width:170px"><el-option v-for="d in departments" :key="d.id" :value="d.id" :label="d.name"/></el-select><el-button type="primary" @click="page=1;load()">查询</el-button></div><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-table :data="rows" v-loading="loading" empty-text="还没有员工档案，点击「新建员工」开始"><el-table-column label="员工" min-width="170"><template #default="{row}"><div class="name-cell"><span class="avatar">{{row.name?.slice(0,1)}}</span><div>{{row.name}}<small>{{row.employeeNo}}</small></div></div></template></el-table-column><el-table-column prop="departmentName" label="部门" min-width="130"/><el-table-column prop="startDate" label="入职日期" width="120"/><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.active?'success':'info'">{{row.active?'在职':'已停用'}}</el-tag></template></el-table-column><el-table-column label="人脸模板" width="110"><template #default="{row}"><el-tag :type="row.faceEnrolled?'success':'warning'">{{row.faceEnrolled?'已录入':'未录入'}}</el-tag></template></el-table-column><el-table-column label="操作" min-width="240" fixed="right"><template #default="{row}"><el-button text type="primary" size="small" @click="edit(row)">编辑</el-button><el-button text type="primary" size="small" :icon="Camera" :disabled="!row.active" @click="enroll(row)">{{row.faceEnrolled?'重新录入':'录入人脸'}}</el-button><el-button v-if="row.faceEnrolled" text type="danger" size="small" @click="deleteFace(row)">删除模板</el-button></template></el-table-column></el-table><div class="pagination"><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="total,prev,pager,next" @current-change="load"/></div></div><el-dialog v-model="dialog" :title="editing?'编辑员工档案':'新建员工档案'" width="620px" :close-on-click-modal="false"><el-alert v-if="formError" :title="formError" type="error" :closable="false"/><el-form label-position="top" @submit.prevent="save"><div class="form-grid"><el-form-item label="工号" required><el-input v-model="form.employeeNo" :disabled="!!editing" maxlength="32"/></el-form-item><el-form-item label="姓名" required><el-input v-model="form.name" maxlength="50"/></el-form-item><el-form-item label="部门" required><el-select v-model="form.departmentId"><el-option v-for="d in departments" :key="d.id" :label="d.name" :value="d.id" :disabled="!d.active"/></el-select></el-form-item><el-form-item v-if="editing" label="在职状态"><el-switch v-model="form.active" :disabled="rows.find(r=>r.id===editing)?.active===false" active-text="在职" inactive-text="停用"/></el-form-item><el-form-item label="入职日期" required><el-date-picker v-model="form.startDate" :disabled="!!editing" type="date" value-format="YYYY-MM-DD" style="width:100%"/></el-form-item><el-form-item v-if="editing" label="停用日期"><el-input :model-value="form.endDate||'停用时由系统记录当天日期'" disabled/></el-form-item><template v-if="!editing"><el-form-item label="登录账号（留空使用工号）"><el-input v-model="form.username" autocomplete="off" maxlength="64"/></el-form-item><el-form-item label="账号权限"><el-select v-model="form.role"><el-option label="员工" value="EMPLOYEE"/><el-option label="管理员" value="ADMIN"/></el-select></el-form-item><el-form-item label="初始密码（留空自动生成）" class="span-2"><el-input v-model="form.password" type="password" show-password autocomplete="new-password"/><div class="help-text">初始密码仅创建时展示一次，请安全交付本人。首次登录必须修改。</div></el-form-item></template></div></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存档案</el-button></template></el-dialog><FaceEnrollment v-model="faceOpen" :employee="selected" @saved="load"/><el-dialog v-model="credentialOpen" title="员工账号已创建" width="440px" :close-on-click-modal="false" @closed="initialPassword='' "><p class="help-text">请将以下初始凭据安全交给员工本人，关闭后无法再次查看。</p><el-descriptions :column="1" border><el-descriptions-item label="账号">{{createdUsername}}</el-descriptions-item><el-descriptions-item label="初始密码"><code>{{initialPassword}}</code></el-descriptions-item></el-descriptions><template #footer><el-button type="primary" @click="credentialOpen=false">已安全记录</el-button></template></el-dialog><el-dialog v-model="departmentOpen" title="部门管理" width="600px"><div class="toolbar"><el-input v-model="departmentName" placeholder="新部门名称" maxlength="50" style="flex:1" @keyup.enter="addDepartment"/><el-button type="primary" :loading="departmentSaving" @click="addDepartment">添加部门</el-button></div><el-table :data="departments"><el-table-column prop="name" label="部门名称"/><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.active?'success':'info'">{{row.active?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="150"><template #default="{row}"><el-button text type="primary" size="small" @click="editDepartment(row)">修改</el-button><el-button text size="small" @click="toggleDepartment(row)">{{row.active?'停用':'启用'}}</el-button></template></el-table-column></el-table></el-dialog></template>
